package com.enterprisehub.api;
import com.enterprisehub.repo.EmployeeRepository; import com.enterprisehub.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final EmployeeRepository users; private final PasswordEncoder encoder; private final JwtService jwt; private final com.enterprisehub.repo.DepartmentRepository departments; public AuthController(EmployeeRepository u,PasswordEncoder e,JwtService j,com.enterprisehub.repo.DepartmentRepository d){users=u;encoder=e;jwt=j;departments=d;} public record Login(@Email String email,@NotBlank String password){} public record Register(@NotBlank String name,@Email String email,@NotBlank String password,Long departmentId){} @PostMapping("/login") public Object login(@Valid @RequestBody Login x){var u=users.findByEmail(x.email()).orElseThrow(()->new org.springframework.security.authentication.BadCredentialsException("Invalid credentials"));if(!encoder.matches(x.password(),u.passwordHash))throw new org.springframework.security.authentication.BadCredentialsException("Invalid credentials");return java.util.Map.of("token",jwt.issue(u.email,u.role),"user",java.util.Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"department",u.department.name));} @PostMapping("/register") public Object register(@Valid @RequestBody Register x){if(x.password().length()<10)throw new IllegalArgumentException("Password must be at least 10 characters");if(users.findByEmail(x.email()).isPresent())throw new IllegalArgumentException("An account with this email already exists");var d=departments.findById(x.departmentId()).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Department not found"));var u=users.save(new com.enterprisehub.domain.Employee(x.name(),x.email(),encoder.encode(x.password()),"EMPLOYEE",d));return java.util.Map.of("token",jwt.issue(u.email,u.role),"user",java.util.Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"department",d.name));} }
